+
+it("does not score a notification without original forecast evidence",()=>{const s=snapshot();s.forecast=[];expect(evaluateReplay(s,frames(d=>d>=0?"RAIN":"NO_RAIN"),now).reason).toBe("INVALID_OR_MISSING_FORECAST_INPUT");});

